use wgpu::util::DeviceExt;

const MAX_DIM: u32 = 512;
const MAX_GENERATIONS: u32 = 1000;
const WORKGROUP: u32 = 16;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = i32(id.x);
    let y = i32(id.y);
    let w = i32(params.width);
    let h = i32(params.height);
    if (x >= w || y >= h) {
        return;
    }

    var neighbours = 0u;
    for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = x + dx;
            let ny = y + dy;
            if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
                neighbours += src[u32(ny * w + nx)];
            }
        }
    }

    let index = u32(y * w + x);
    let alive = src[index] == 1u;
    let next = (alive && (neighbours == 2u || neighbours == 3u)) || (!alive && neighbours == 3u);
    dst[index] = select(0u, 1u, next);
}
"#;

struct Grid {
    width: u32,
    height: u32,
    generations: u32,
    cells: Vec<u32>,
}

fn parse_input(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_whitespace();
    let mut header = [0u32; 3];
    for value in &mut header {
        let token = tokens.next().ok_or("input is missing the header")?;
        *value = token
            .parse()
            .map_err(|_| format!("bad header value {token:?}"))?;
    }
    let [width, height, generations] = header;
    if !(1..=MAX_DIM).contains(&width) || !(1..=MAX_DIM).contains(&height) {
        return Err(format!("width and height must be 1..={MAX_DIM}, got {width}x{height}"));
    }
    if generations > MAX_GENERATIONS {
        return Err(format!("generations must be 0..={MAX_GENERATIONS}, got {generations}"));
    }

    let expected = width as usize * height as usize;
    let mut cells = Vec::with_capacity(expected);
    for token in tokens {
        for ch in token.chars() {
            match ch {
                '0' => cells.push(0),
                '1' => cells.push(1),
                other => return Err(format!("bad cell character {other:?}")),
            }
        }
    }
    if cells.len() < expected {
        return Err(format!("expected {expected} cells, found {}", cells.len()));
    }
    cells.truncate(expected);

    Ok(Grid {
        width,
        height,
        generations,
        cells,
    })
}

