        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("life pipeline"),
        layout: Some(&pipeline_layout),
        module: &shader,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("life generations"),
    });
    for generation in 0..grid.generations {
        // Each compute pass ends with a full barrier, so generation n+1 sees all writes of n.
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("life generation"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[(generation % 2) as usize], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    // After an even number of steps the result is back in buffer a.
    let result = &buffers[(grid.generations % 2) as usize];
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (sender, receiver) = mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |result| {
        let _ = sender.send(result);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    receiver
        .recv()
        .map_err(|e| format!("map callback lost: {e}"))?
        .map_err(|e| format!("cannot read back GPU buffer: {e}"))?;

    let cells = {
        let data = slice.get_mapped_range();
        data.chunks_exact(4)
            .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect::<Vec<u32>>()
    };
    readback.unmap();
    Ok(cells)
}

fn write_grid(grid: &Grid, cells: &[u32]) -> io::Result<()> {
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    let width = grid.width as usize;
    let mut alive = 0usize;
    for row in cells.chunks(width) {
        let line: Vec<&str> = row
            .iter()
            .map(|&cell| {
                alive += cell as usize;
                if cell == 1 { "1" } else { "0" }
            })
            .collect();
        writeln!(out, "{}", line.join(" "))?;
    }
    writeln!(out, "ALIVE {alive}")?;
    out.flush()
}

fn run() -> Result<(), String> {
    let path = env::args()
        .nth(1)
        .ok_or("usage: life <input-file>")?;
    let text = fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let grid = parse_input(&text)?;
    let cells = pollster::block_on(simulate(&grid))?;
    write_grid(&grid, &cells).map_err(|e| format!("cannot write output: {e}"))
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("error: {message}");
            ExitCode::FAILURE
        }
    }
}

use std::env;
use std::fs;
use std::io::{self, BufWriter, Write};
use std::process::ExitCode;
use std::sync::mpsc;

use wgpu::util::DeviceExt;

const MAX_DIM: u32 = 512;
const MAX_GENERATIONS: u32 = 1000;
const WORKGROUP: u32 = 16;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = i32(id.x);
    let y = i32(id.y);
    let w = i32(params.width);
    let h = i32(params.height);
    if (x >= w || y >= h) {
        return;
    }

    var neighbours = 0u;
    for (var dy = -1; dy <= 1; dy++) {
        for (var dx = -1; dx <= 1; dx++) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = x + dx;
            let ny = y + dy;
            if (nx >= 0 && nx < w && ny >= 0 && ny < h) {
                neighbours += src[u32(ny * w + nx)];
            }
        }
    }

    let index = u32(y * w + x);
    let alive = src[index] == 1u;
    let next = (alive && (neighbours == 2u || neighbours == 3u)) || (!alive && neighbours == 3u);
    dst[index] = select(0u, 1u, next);
}
"#;

struct Grid {
    width: u32,
    height: u32,
    generations: u32,
    cells: Vec<u32>,
}

fn parse_input(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_whitespace();
    let mut header = [0u32; 3];
    for value in &mut header {
        let token = tokens.next().ok_or("input is missing the header")?;
        *value = token
            .parse()
            .map_err(|_| format!("bad header value {token:?}"))?;
    }
    let [width, height, generations] = header;
    if !(1..=MAX_DIM).contains(&width) || !(1..=MAX_DIM).contains(&height) {
        return Err(format!("width and height must be 1..={MAX_DIM}, got {width}x{height}"));
    }
    if generations > MAX_GENERATIONS {
        return Err(format!("generations must be 0..={MAX_GENERATIONS}, got {generations}"));
    }

    let expected = width as usize * height as usize;
    let mut cells = Vec::with_capacity(expected);
    for token in tokens {
        for ch in token.chars() {
            match ch {
                '0' => cells.push(0),
                '1' => cells.push(1),
                other => return Err(format!("bad cell character {other:?}")),
            }
        }
    }
    if cells.len() < expected {
        return Err(format!("expected {expected} cells, found {}", cells.len()));
    }
    cells.truncate(expected);

    Ok(Grid {
        width,
        height,
        generations,
        cells,
    })
}

async fn simulate(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
            apply_limit_buckets: false,
        })
        .await
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor {
            label: Some("life"),
            ..Default::default()
        })
        .await
        .map_err(|e| format!("cannot create GPU device: {e}"))?;

    let size = (grid.cells.len() * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let storage_usage = wgpu::BufferUsages::STORAGE
        | wgpu::BufferUsages::COPY_DST
        | wgpu::BufferUsages::COPY_SRC;
    let buffers = [
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("life a"),
            contents: bytemuck::cast_slice(&grid.cells),
            usage: storage_usage,
        }),
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("life b"),
            size,
            usage: storage_usage,
            mapped_at_creation: false,
        }),
    ];
    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&[grid.width, grid.height, 0u32, 0u32]),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("life layout"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 1,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: true },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 2,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: false },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
        ],
    });

    // Two bind groups so that each generation reads one buffer and writes the other.
    let make_bind_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("life step"),
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: src.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: dst.as_entire_binding(),
                },
            ],
        })
    };
    let bind_groups = [
        make_bind_group(&buffers[0], &buffers[1]),
        make_bind_group(&buffers[1], &buffers[0]),
    ];

    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("life pipeline layout"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("life shader"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("life pipeline"),
        layout: Some(&pipeline_layout),
        module: &shader,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    let groups_x = grid.width.div_ceil(WORKGROUP);
    let groups_y = grid.height.div_ceil(WORKGROUP);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("life generations"),
    });
    for generation in 0..grid.generations {
        // Each compute pass ends with a full barrier, so generation n+1 sees all writes of n.
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("life generation"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[(generation % 2) as usize], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    // After an even number of steps the result is back in buffer a.
    let result = &buffers[(grid.generations % 2) as usize];
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (sender, receiver) = mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |result| {
        let _ = sender.send(result);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    receiver
        .recv()
        .map_err(|e| format!("map callback lost: {e}"))?
        .map_err(|e| format!("cannot read back GPU buffer: {e}"))?;

    let cells = {
        let data = slice.get_mapped_range();
        data.chunks_exact(4)
            .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
            .collect::<Vec<u32>>()
    };
    readback.unmap();
    Ok(cells)
}

fn write_grid(grid: &Grid, cells: &[u32]) -> io::Result<()> {
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    let width = grid.width as usize;
    let mut alive = 0usize;
    for row in cells.chunks(width) {
        let line: Vec<&str> = row
            .iter()
            .map(|&cell| {
                alive += cell as usize;
                if cell == 1 { "1" } else { "0" }
            })
            .collect();
        writeln!(out, "{}", line.join(" "))?;
    }
    writeln!(out, "ALIVE {alive}")?;
    out.flush()
}

fn run() -> Result<(), String> {
    let path = env::args()
        .nth(1)
        .ok_or("usage: life <input-file>")?;
    let text = fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let grid = parse_input(&text)?;
    let cells = pollster::block_on(simulate(&grid))?;
    write_grid(&grid, &cells).map_err(|e| format!("cannot write output: {e}"))
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("error: {message}");
            ExitCode::FAILURE
        }
    }
}

import sys
def load(p):
    t = open(p).read().split()
    w, h, g = int(t[0]), int(t[1]), int(t[2])
    digits = [int(c) for c in t[3:] if c in "01"]
    grid = [digits[r*w:(r+1)*w] for r in range(h)]
    return w, h, g, grid
w, h, g, grid = load(sys.argv[1])
for _ in range(g):
    new = [[0]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            n = 0
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    if dx or dy:
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w:
                            n += grid[ny][nx]
            new[y][x] = 1 if (n == 3 or (grid[y][x] and n == 2)) else 0
    grid = new
for row in grid:
    print(" ".join(map(str,row)))
print("ALIVE", sum(sum(r) for r in grid))
